import 'dart:math';import 'package:flutter/material.dart';import '../data/app_database.dart';
class GamesScreen extends StatefulWidget{final AppDatabase db;const GamesScreen({super.key,required this.db});@override State<GamesScreen> createState()=>_GamesState();}
class _GamesState extends State<GamesScreen>{String lang='ar';Map<String,dynamic>? word;int score=0;final r=Random();@override void initState(){super.initState();newWord();}Future<void>newWord()async{final w=await widget.db.words(lang);if(w.isNotEmpty)setState(()=>word=w[r.nextInt(w.length)]);}
@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text('🎮 تحدي المفردات',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:20),if(word!=null)Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Text(word!['text'].toString(),style:const TextStyle(fontSize:40,fontWeight:FontWeight.bold)),Text(word!['example'].toString()),const SizedBox(height:20),FilledButton(onPressed:(){setState(()=>score++);newWord();},child:const Text('عرفتها ✓')),OutlinedButton(onPressed:newWord,child:const Text('كلمة أخرى'))]))),Text('النقاط: '+score.toString())])));}
}
